SELECT 'all 29 notable NPCs are in' AS assertion, count(*) AS got, 29 AS want
  FROM notable_npcs WHERE slug IN ('brethan-dzir', 'coran-dzir', 'leizak-dzir', 'alistair-dunscon', 'mestoph-denali', 'kara-zayne', 'dan-ironforge', 'kzaa', 'dragonbane', 'power-master', 'task-master', 'shadow-master', 'brain-storm', 'gold-falcon', 'james-lome', 'sylvain-richard', 'julie-tremblay', 'jean-desjardins', 'robert-miller', 'robert-carlye', 'gwen-severson', 'jacob-whispering-wind', 'essai-ramirez', 'katherine-delgado', 'thadius-geller', 'roderick-warrington-iii', 'arthur-night', 'knight-hunter', 'knife-master');
